--- 由 currentId 沿 parent 回溯得到根→当前的 id 链（存档里无链表，按需重建）
local function chainOf(nodes, currentId)
    local chain = {}
    local cur = nil
    do
        local i = 0
        while i < #nodes do
            if nodes[i + 1].id == currentId then
                cur = nodes[i + 1]
                break
            end
            i = i + 1
        end
    end
    while cur ~= nil do
        chain:unshift(cur.id)
        local next = nil
        if cur.parent ~= "" then
            do
                local i = 0
                while i < #nodes do
                    if nodes[i + 1].id == cur.parent then
                        next = nodes[i + 1]
                        break
                    end
                    i = i + 1
                end
            end
        end
        cur = next
    end
    return chain
end
