function TreeGallery.prototype.open(self, entries)
    self.entries = entries
    self.sel = Math:max(
        0,
        Math:min(self.sel, #entries - 1)
    )
    self.scroll = 0
    self.openFlag = true
    self.root.visible = true
    self.hit.touchEnabled = true
    self:render()
end
function TreeGallery.prototype.close(self)
    self.openFlag = false
    self.root.visible = false
    self.hit.touchEnabled = false
end
function TreeGallery.prototype.isOpen(self)
    return self.openFlag
end
function TreeGallery.prototype.handleKey(self, key)
    if not self.openFlag then
        return
    end
    if key == "Escape" or key == "Q" then
        self:close()
    elseif key == "W" or key == "Up" then
        self:moveSel(-1)
    elseif key == "S" or key == "Down" then
        self:moveSel(1)
    elseif key == "A" or key == "Left" then
        self:moveSel(-self.visibleRows)
    elseif key == "D" or key == "Right" then
        self:moveSel(self.visibleRows)
    end
end
function TreeGallery.prototype.moveSel(self, delta)
    if #self.entries == 0 then
        return
    end
    local s = self.sel + delta
    if s < 0 then
        s = 0
    end
    if s > #self.entries - 1 then
        s = #self.entries - 1
    end
    if s ~= self.sel then
        self.sel = s
        self:render()
    end
end
